    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 20000 * 1024;
    unsigned char *data = malloc(n);
    memset(data, 0x5a, n);
    unsigned char out[32];

