        uint32_t x = w[i-15];
        uint32_t y = w[i-2];
        uint32_t s0 = ROR(x, 7) ^ ROR(x, 18) ^ (x >> 3);
        uint32_t s1 = ROR(y, 17) ^ ROR(y, 19) ^ (y >> 10);
        w[i] = w[i-16] + s0 + w[i-7] + s1;
