#include <stdio.h>
#include <immintrin.h>
#include <time.h>
#include <stdint.h>
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
int main(){
    /* 1e9 dependent vpaddd vs 8-way independent */
    __m256i a = _mm256_set1_epi32(1);
    __m256i b = _mm256_set1_epi32(3);
    double t0 = now();
    for (int i = 0; i < 100000000; i++) {
        a = _mm256_add_epi32(a, b);
    }
    double t1 = now();
    volatile int sink = _mm256_extract_epi32(a, 0);
    printf("dep 1e8 vpaddd: %.4f s  sink %d\n", t1-t0, sink);

    __m256i x[8];
    for (int i = 0; i < 8; i++) x[i] = _mm256_set1_epi32(i+1);
    t0 = now();
    for (int i = 0; i < 100000000; i++) {
        x[0] = _mm256_add_epi32(x[0], b);
        x[1] = _mm256_add_epi32(x[1], b);
        x[2] = _mm256_add_epi32(x[2], b);
        x[3] = _mm256_add_epi32(x[3], b);
        x[4] = _mm256_add_epi32(x[4], b);
        x[5] = _mm256_add_epi32(x[5], b);
        x[6] = _mm256_add_epi32(x[6], b);
        x[7] = _mm256_add_epi32(x[7], b);
    }
    t1 = now();
    sink = _mm256_extract_epi32(x[0],0)+_mm256_extract_epi32(x[7],0);
    printf("8-way 1e8*8 vpaddd: %.4f s  sink %d\n", t1-t0, sink);
    return 0;
}
